// ─── Tipos ───────────────────────────────────────────────────────────────────
interface Execution {
  id: string; publico: string; solucao: string; mes: string;
  codSolucao: string; codFoco: string; codEvento: string;
}
interface MuniData { executions: Execution[]; startupAtendida: boolean; eli: boolean; }
type Territorios = Record<string, MuniData>;

// ─── Constantes ───────────────────────────────────────────────────────────────
const PUBLICOS = [
  { key: "gov", label: ".GOV", desc: "Prefeituras",  icon: Landmark,      color: "#3B6E5C" },
  { key: "edu", label: ".EDU", desc: "Educação",    icon: GraduationCap, color: "#B5562C" },
  { key: "com", label: ".COM", desc: "Empresas",    icon: Building2,     color: "#3A5A8C" },
];
const MESES = ["janeiro","fevereiro","março","abril","maio","junho",
               "julho","agosto","setembro","outubro","novembro","dezembro"];
const MUNICIPIOS_SE = SE_GEO.map((f: { name: string }) => f.name).sort((a: string, b: string) => a.localeCompare(b, "pt-BR"));
const uid = () => Math.random().toString(36).slice(2, 10) + Date.now().toString(36);

// ─── Regras de negócio ────────────────────────────────────────────────────────
function computeStatus(data: MuniData) {
  const pubs = new Set(data.executions.map((e) => e.publico));
  const ativado = pubs.size >= 2;
  const impulso = (ativado || data.eli) && data.startupAtendida;
  return { ativado, impulso, qtdPublicos: pubs.size };
}
function emptyMuni(): MuniData { return { executions: [], startupAtendida: false, eli: false }; }

// ─── Mapa SVG ─────────────────────────────────────────────────────────────────
function ringToPath(ring: number[][]): string {
  if (!ring || ring.length < 2) return "";
  return "M " + ring.map(([x, y]) => `${x},${y}`).join(" L ") + " Z";
}
function centroid(ring: number[][]): [number, number] {
  let cx = 0, cy = 0;
  for (const [x, y] of ring) { cx += x; cy += y; }
  return [cx / ring.length, cy / ring.length];
}
function getFill(data: MuniData): string {
  const { ativado, impulso } = computeStatus(data);
  if (impulso) return "#F4C95D";
  if (ativado) return "#1F4D3D";
  if (data.executions.length > 0) return "#C8623A";
  return "#C9C0B2";
}

interface MapaProps { territorios: Territorios; onSelect: (n: string) => void; selected: string | null; }

function MapaSergipe({ territorios, onSelect, selected }: MapaProps) {
  const [tip, setTip] = useState<{ name: string; cx: number; cy: number } | null>(null);
  const getMuni = (n: string): MuniData => territorios[n] || emptyMuni();

  return (
    <div style={{ background: "#fff", border: "1px solid #EFE8DA", borderRadius: 16, padding: "16px 20px 12px", marginBottom: 24 }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 10, flexWrap: "wrap", gap: 8 }}>
        <span style={{ fontWeight: 700, fontSize: 14, color: "#2A2520" }}>Mapa dos Territórios — Sergipe</span>
        <div style={{ display: "flex", gap: 14, flexWrap: "wrap", fontSize: 12, color: "#6B6259" }}>
          {([["#1F4D3D","Ativado",false],["#F4C95D","Conta p/ Impulso",true],["#C8623A","Em andamento",false],["#C9C0B2","Sem ação",false]] as [string,string,boolean][]).map(([c, l, b]) => (
            <div key={l} style={{ display: "flex", alignItems: "center", gap: 5 }}>
              <span style={{ width: 11, height: 11, borderRadius: "50%", background: c, border: b ? "2px solid #9A7B1E" : "1px solid rgba(0,0,0,0.15)", display: "inline-block" }} />
              <span>{l}</span>
            </div>
          ))}
        </div>
      </div>
      <svg viewBox="0 0 500 700" style={{ width: "100%", maxWidth: 500, display: "block", background: "#D6EAF5", borderRadius: 10, border: "1px solid #B8D4E8" }} onMouseLeave={() => setTip(null)}>
        <rect width={500} height={700} fill="#D6EAF5" />
        {(SE_GEO as { name: string; rings: number[][][] }[]).map(({ name, rings }) => {
          const data = getMuni(name);
          const fill = getFill(data);
          const { impulso } = computeStatus(data);
          const isSel = name === selected;
          const [cx, cy] = centroid(rings[0]);
          return (
            <g key={name} style={{ cursor: "pointer" }} onClick={() => onSelect(name)}
               onMouseEnter={() => setTip({ name, cx, cy })} onMouseLeave={() => setTip(null)}>
              {rings.map((r: number[][], i: number) => (
                <path key={i} d={ringToPath(r)} fill={fill}
                  stroke={isSel ? "#fff" : impulso ? "#9A7B1E" : "#fff"}
                  strokeWidth={isSel ? "2.5" : impulso ? "2" : "0.8"} />
              ))}
              {impulso && rings.map((r: number[][], i: number) => (
                <path key={"i" + i} d={ringToPath(r)} fill="none" stroke="#C9A53C" strokeWidth="2" strokeDasharray="5 3" style={{ pointerEvents: "none" }} />
              ))}
              {isSel && rings.map((r: number[][], i: number) => (
                <path key={"s" + i} d={ringToPath(r)} fill="none" stroke="#fff" strokeWidth="3" style={{ pointerEvents: "none" }} />
              ))}
            </g>
          );
        })}
        {tip && (() => {
          const data = getMuni(tip.name);
          const { ativado, impulso, qtdPublicos } = computeStatus(data);
          const fill = getFill(data);
          const status = impulso ? "✦ Conta p/ Impulso" : ativado ? "✔ Ativado" : qtdPublicos === 1 ? "⚡ Em andamento" : "○ Sem ação";
          const bw = 168, bh = 50;
          let bx = tip.cx + 12, by = tip.cy - bh / 2;
          if (bx + bw > 496) bx = tip.cx - bw - 12;
          if (by < 4) by = 4;
          if (by + bh > 696) by = 696 - bh;
          const words = tip.name.split(" ");
          const half = Math.ceil(words.length / 2);
          const l1 = words.slice(0, half).join(" "), l2 = words.slice(half).join(" ");
          return (
            <g style={{ pointerEvents: "none" }}>
              <rect x={bx} y={by} width={bw} height={bh} rx="7" fill="#1E1A16" opacity="0.92" />
              <text x={bx + 10} y={by + 15} fontSize="11.5" fontWeight="700" fill="#fff" fontFamily="Inter,sans-serif">{l1}</text>
              {l2 && <text x={bx + 10} y={by + 27} fontSize="11.5" fontWeight="700" fill="#fff" fontFamily="Inter,sans-serif">{l2}</text>}
              <rect x={bx + 10} y={by + 32} width={8} height={8} rx="2" fill={fill} />
              <text x={bx + 22} y={by + 41} fontSize="10" fill="#D8CFC0" fontFamily="Inter,sans-serif">{status}</text>
              {data.eli && <text x={bx + bw - 32} y={by + 41} fontSize="9" fill="#B8A8E0" fontFamily="Inter,sans-serif" fontWeight="700">ELI</text>}
            </g>
          );
        })()}
      </svg>
    </div>
  );
}

// ─── App principal ────────────────────────────────────────────────────────────
export default function AtivaSergipe() {
  const [loading,     setLoading]     = useState(true);
  const [saving,      setSaving]      = useState(false);
  const [territorios, setTerritorios] = useState<Territorios>({});
  const [search,      setSearch]      = useState("");
  const [filter,      setFilter]      = useState("todos");
  const [openMuni,    setOpenMuni]    = useState<string | null>(null);

  useEffect(() => {
    fetch("/api/territorios")
      .then((r) => r.json())
      .then((d) => { setTerritorios(d || {}); setLoading(false); })
      .catch(() => setLoading(false));
  }, []);

  const persist = useCallback(async (next: Territorios) => {
    setTerritorios(next);
    setSaving(true);
    await fetch("/api/territorios", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(next),
    });
    setSaving(false);
  }, []);

  const getMuni = (n: string): MuniData => territorios[n] || emptyMuni();

  const stats = useMemo(() => {
    let ativados = 0, impulso = 0, andamento = 0, semAcao = 0;
    MUNICIPIOS_SE.forEach((m) => {
      const d = getMuni(m), { ativado, impulso: imp } = computeStatus(d);
      if (imp) impulso++;
      if (ativado) ativados++;
      else if (d.executions.length > 0) andamento++;
      else semAcao++;
    });
    return { ativados, impulso, andamento, semAcao, total: MUNICIPIOS_SE.length };
  }, [territorios]);

  const filtered = useMemo(() => MUNICIPIOS_SE.filter((m) => {
    if (search && !m.toLowerCase().includes(search.toLowerCase())) return false;
    const d = getMuni(m), { ativado, impulso } = computeStatus(d);
    if (filter === "ativado"   && !ativado)                          return false;
    if (filter === "impulso"   && !impulso)                          return false;
    if (filter === "andamento" && (d.executions.length === 0 || ativado)) return false;
    if (filter === "sem-acao"  && d.executions.length > 0)           return false;
    return true;
  }), [search, filter, territorios]);

  function handleSelect(nome: string) {
    setOpenMuni(nome); setSearch(""); setFilter("todos");
    setTimeout(() => {
      document.getElementById("muni-" + nome.replace(/\s+/g, "-"))?.scrollIntoView({ behavior: "smooth", block: "start" });
    }, 120);
  }

  if (loading) return (
    <div style={{ display: "flex", alignItems: "center", justifyContent: "center", height: 400, fontFamily: "Inter,sans-serif", color: "#6B6259" }}>
      Carregando…
    </div>
  );

  return (
    <div style={{ fontFamily: "Inter,-apple-system,sans-serif", background: "#FAF7F2", minHeight: "100vh", color: "#2A2520" }}>
      <style>{`*{box-sizing:border-box}button,input,select{font-family:inherit;cursor:pointer}.fade-in{animation:fi .22s ease}@keyframes fi{from{opacity:0;transform:translateY(-4px)}to{opacity:1;transform:none}}::-webkit-scrollbar{width:6px;height:6px}::-webkit-scrollbar-thumb{background:#D8CFC0;border-radius:3px}`}</style>
      <div style={{ maxWidth: 1100, margin: "0 auto", padding: "28px 20px 80px" }}>

        {/* Header */}
        <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", flexWrap: "wrap", gap: 14, marginBottom: 24 }}>
          <div>
            <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 3 }}>
              <div style={{ width: 36, height: 36, borderRadius: 10, background: "#1F4D3D", display: "flex", alignItems: "center", justifyContent: "center" }}>
                <Zap size={18} color="#F4C95D" strokeWidth={2.5} />
              </div>
              <h1 style={{ fontSize: 26, fontWeight: 700, margin: 0, letterSpacing: -.5 }}>Ativa Sergipe</h1>
            </div>
            <p style={{ margin: 0, color: "#857A6C", fontSize: 14 }}>Acompanhamento da ativação de inovação nos territórios · Sebrae/SE</p>
          </div>
          <div style={{ fontSize: 12.5, color: saving ? "#B5562C" : "#9C9286", display: "flex", alignItems: "center", gap: 6 }}>
            <span style={{ width: 7, height: 7, borderRadius: "50%", background: saving ? "#B5562C" : "#6FA287", display: "inline-block" }} />
            {saving ? "salvando…" : "sincronizado"}
          </div>
        </div>

        {/* Stat cards */}
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(185px,1fr))", gap: 11, marginBottom: 22 }}>
          {([
            { label: "Territórios ativados", val: stats.ativados,  color: "#1F4D3D", Icon: CheckCircle2 },
            { label: "Indicador Impulso",    val: stats.impulso,   color: "#C9A53C", Icon: Rocket,      dark: true },
            { label: "Em andamento",         val: stats.andamento, color: "#B5562C", Icon: AlertCircle },
            { label: "Sem ação registrada",  val: stats.semAcao,   color: "#9C9286", Icon: Circle },
          ] as { label:string; val:number; color:string; Icon:React.ElementType; dark?:boolean }[]).map(({ label, val, color, Icon, dark }) => (
            <div key={label} style={{ background: "#fff", border: "1px solid #EFE8DA", borderRadius: 13, padding: "14px 16px" }}>
              <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 8 }}>
                <span style={{ fontSize: 11.5, color: "#857A6C", fontWeight: 600, textTransform: "uppercase", letterSpacing: .4 }}>{label}</span>
                <div style={{ width: 25, height: 25, borderRadius: 7, background: color, display: "flex", alignItems: "center", justifyContent: "center" }}>
                  <Icon size={13} color={dark ? "#2A2520" : "#fff"} strokeWidth={2.3} />
                </div>
              </div>
              <div style={{ display: "flex", alignItems: "baseline", gap: 5, marginBottom: 8 }}>
                <span style={{ fontSize: 28, fontWeight: 700, lineHeight: 1 }}>{val}</span>
                <span style={{ fontSize: 13, color: "#9C9286" }}>/ {stats.total} ({Math.round(val / stats.total * 100)}%)</span>
              </div>
              <div style={{ height: 4, background: "#F1EBDD", borderRadius: 2, overflow: "hidden" }}>
                <div style={{ width: `${Math.round(val / stats.total * 100)}%`, height: "100%", background: color }} />
              </div>
            </div>
          ))}
        </div>

        {/* Mapa */}
        <MapaSergipe territorios={territorios} onSelect={handleSelect} selected={openMuni} />

        {/* Filtros */}
        <div style={{ display: "flex", gap: 9, flexWrap: "wrap", alignItems: "center", marginBottom: 14 }}>
          <div style={{ position: "relative", flex: "1 1 220px" }}>
            <Search size={14} style={{ position: "absolute", left: 11, top: "50%", transform: "translateY(-50%)", color: "#9C9286" }} />
            <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Buscar município…"
              style={{ width: "100%", padding: "8px 10px 8px 32px", borderRadius: 8, border: "1px solid #E5DDD0", background: "#fff", fontSize: 13.5, outline: "none" }} />
          </div>
          {([["todos","Todos"],["ativado","Ativados"],["impulso","Indicador Impulso"],["andamento","Em andamento"],["sem-acao","Sem ação"]] as [string,string][]).map(([k, l]) => (
            <button key={k} onClick={() => setFilter(k)}
              style={{ padding: "7px 12px", borderRadius: 8, fontSize: 13, fontWeight: 600, border: filter === k ? "1px solid #1F4D3D" : "1px solid #E5DDD0", background: filter === k ? "#1F4D3D" : "#fff", color: filter === k ? "#fff" : "#6B6259" }}>
              {l}
            </button>
          ))}
        </div>

        {/* Legenda */}
        <div style={{ display: "flex", gap: 14, flexWrap: "wrap", fontSize: 12.5, color: "#857A6C", marginBottom: 16, padding: "9px 13px", background: "#F1EBDD", borderRadius: 9 }}>
          <span style={{ display: "flex", alignItems: "center", gap: 5 }}><span style={{ width: 10, height: 10, borderRadius: 3, background: "#1F4D3D", display: "inline-block" }} />Ativado (2+ públicos)</span>
          <span style={{ display: "flex", alignItems: "center", gap: 5 }}><span style={{ width: 10, height: 10, borderRadius: 3, background: "#F4C95D", border: "1px solid #9A7B1E", display: "inline-block" }} />Conta p/ Indicador Impulso</span>
          <span style={{ display: "flex", alignItems: "center", gap: 5 }}><span style={{ width: 10, height: 10, borderRadius: 3, background: "#C8623A", display: "inline-block" }} />Em andamento (1 público)</span>
          <span style={{ marginLeft: "auto", fontSize: 12 }}>Regra: 2 soluções para públicos diferentes (.GOV / .EDU / .COM) ativa o território.</span>
        </div>

        {/* Lista */}
        <div style={{ display: "flex", flexDirection: "column", gap: 7 }}>
          {filtered.length === 0 && <div style={{ textAlign: "center", padding: 40, color: "#9C9286", fontSize: 14 }}>Nenhum território encontrado.</div>}
          {filtered.map((m) => (
            <MuniCard key={m} nome={m} data={getMuni(m)} status={computeStatus(getMuni(m))}
              isOpen={openMuni === m} onToggle={() => setOpenMuni(openMuni === m ? null : m)}
              onAddExec={(ex: Omit<Execution,"id">) => persist({ ...territorios, [m]: { ...getMuni(m), executions: [...getMuni(m).executions, { id: uid(), ...ex }] } })}
              onDelExec={(id: string) => persist({ ...territorios, [m]: { ...getMuni(m), executions: getMuni(m).executions.filter((e) => e.id !== id) } })}
              onFlag={(f: string, v: boolean) => persist({ ...territorios, [m]: { ...getMuni(m), [f]: v } })} />
          ))}
        </div>
      </div>
    </div>
  );
}

// ─── Card de município ────────────────────────────────────────────────────────
interface CardProps {
  nome: string; data: MuniData;
  status: { ativado: boolean; impulso: boolean; qtdPublicos: number };
  isOpen: boolean; onToggle: () => void;
  onAddExec: (e: Omit<Execution,"id">) => void;
  onDelExec: (id: string) => void;
  onFlag: (f: string, v: boolean) => void;
}
function MuniCard({ nome, data, status, isOpen, onToggle, onAddExec, onDelExec, onFlag }: CardProps) {
  const [formOpen, setFormOpen] = useState(false);
  const { ativado, impulso, qtdPublicos } = status;
  const border  = impulso ? "#F4C95D" : ativado ? "#1F4D3D" : data.executions.length > 0 ? "#C8623A" : "#EFE8DA";
  const sBg     = impulso ? "#FBF0CF" : ativado ? "#E4EEE8" : data.executions.length > 0 ? "#F8E6DC" : "#F1EBDD";
  const sColor  = impulso ? "#9A7B1E" : ativado ? "#1F4D3D" : data.executions.length > 0 ? "#B5562C" : "#9C9286";
  const sLabel  = impulso ? "✦ Conta p/ Impulso" : ativado ? "✔ Ativado" : data.executions.length > 0 ? "⚡ Em andamento" : "Sem ação";

  return (
    <div id={"muni-" + nome.replace(/\s+/g, "-")} style={{ background: "#fff", border: `1px solid ${isOpen ? border : "#EFE8DA"}`, borderLeft: `4px solid ${border}`, borderRadius: 11, overflow: "hidden" }}>
      <div onClick={onToggle} style={{ display: "flex", alignItems: "center", gap: 10, padding: "11px 14px", cursor: "pointer" }}>
        {isOpen ? <ChevronDown size={15} color="#9C9286" /> : <ChevronRight size={15} color="#9C9286" />}
        <span style={{ fontWeight: 600, fontSize: 14, flex: 1 }}>{nome}</span>
        <div style={{ display: "flex", gap: 4 }}>
          {PUBLICOS.map((p) => {
            const has = data.executions.some((e) => e.publico === p.key);
            return (
              <div key={p.key} title={p.label} style={{ width: 23, height: 23, borderRadius: 6, display: "flex", alignItems: "center", justifyContent: "center", background: has ? p.color : "#F1EBDD", opacity: has ? 1 : .5 }}>
                <p.icon size={12} color={has ? "#fff" : "#9C9286"} strokeWidth={2.3} />
              </div>
            );
          })}
        </div>
        {data.eli && <span style={{ fontSize: 10, fontWeight: 700, padding: "2px 6px", borderRadius: 4, background: "#E8E2F3", color: "#5C4A8C" }}>ELI</span>}
        <span style={{ fontSize: 11, fontWeight: 700, padding: "3px 9px", borderRadius: 6, background: sBg, color: sColor, whiteSpace: "nowrap" }}>{sLabel}</span>
      </div>

      {isOpen && (
        <div className="fade-in" style={{ padding: "0 14px 14px", borderTop: "1px solid #F4EFE5" }}>
          <div style={{ display: "flex", gap: 18, flexWrap: "wrap", padding: "12px 0 8px" }}>
            {([["startupAtendida", "Startup atendida no município"], ["eli", "Participa do ELI"]] as [string, string][]).map(([f, l]) => (
              <label key={f} style={{ display: "flex", alignItems: "center", gap: 7, fontSize: 13, color: "#4A443B", cursor: "pointer" }}>
                <input type="checkbox" checked={!!(data as Record<string,unknown>)[f]} onChange={(e) => onFlag(f, e.target.checked)} style={{ width: 15, height: 15, accentColor: "#1F4D3D" }} />
                {l}
              </label>
            ))}
          </div>

          {qtdPublicos > 0 && !ativado && (
            <div style={{ fontSize: 12.5, color: "#B5562C", background: "#F8E6DC", padding: "7px 11px", borderRadius: 7, marginBottom: 10, display: "flex", gap: 5, alignItems: "center" }}>
              <AlertCircle size={13} /> Falta executar ação para mais {2 - qtdPublicos} público{2 - qtdPublicos > 1 ? "s" : ""} diferente{2 - qtdPublicos > 1 ? "s" : ""}.
            </div>
          )}

          {data.executions.length > 0 && (
            <div style={{ overflowX: "auto", marginBottom: 10 }}>
              <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13 }}>
                <thead>
                  <tr style={{ color: "#9C9286", fontSize: 11, textTransform: "uppercase" }}>
                    {["Público", "Solução / Evento", "Mês", "Cód. solução", "Cód. FOCO", "Cód. evento", ""].map((h) => (
                      <th key={h} style={{ padding: "5px 8px", textAlign: "left", whiteSpace: "nowrap" }}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {data.executions.map((e) => {
                    const pub = PUBLICOS.find((p) => p.key === e.publico)!;
                    return (
                      <tr key={e.id} style={{ borderTop: "1px solid #F4EFE5" }}>
                        <td style={{ padding: "7px 8px" }}><span style={{ fontSize: 10.5, fontWeight: 700, padding: "2px 6px", borderRadius: 4, background: pub.color, color: "#fff" }}>{pub.label}</span></td>
                        <td style={{ padding: "7px 8px", fontWeight: 500 }}>{e.solucao}</td>
                        <td style={{ padding: "7px 8px", color: "#6B6259" }}>{e.mes || "—"}</td>
                        <td style={{ padding: "7px 8px", color: "#6B6259" }}>{e.codSolucao || "—"}</td>
                        <td style={{ padding: "7px 8px", color: "#6B6259" }}>{e.codFoco || "—"}</td>
                        <td style={{ padding: "7px 8px", color: "#6B6259" }}>{e.codEvento || "—"}</td>
                        <td style={{ padding: "7px 8px" }}>
                          <button onClick={() => onDelExec(e.id)} style={{ background: "none", border: "none", padding: 3, display: "flex" }}>
                            <Trash2 size={13} color="#C9A53C" />
                          </button>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}

          {!formOpen
            ? <button onClick={() => setFormOpen(true)} style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 13, fontWeight: 600, color: "#1F4D3D", background: "#E4EEE8", border: "none", padding: "7px 13px", borderRadius: 7 }}>
                <Plus size={13} /> Registrar execução
              </button>
            : <ExecForm onCancel={() => setFormOpen(false)} onSubmit={(ex) => { onAddExec(ex); setFormOpen(false); }} />
          }
        </div>
      )}
    </div>
  );
}

// ─── Formulário de execução ───────────────────────────────────────────────────
interface ExecFormProps { onCancel: () => void; onSubmit: (e: Omit<Execution,"id">) => void; }
function ExecForm({ onCancel, onSubmit }: ExecFormProps) {
  const [pub, setPub] = useState("gov");
  const [sol, setSol] = useState("");
  const [mes, setMes] = useState("");
  const [cs,  setCs]  = useState("");
  const [cf,  setCf]  = useState("");
  const [ce,  setCe]  = useState("");

  const fi = (label: string, val: string, set: (v: string) => void, ph: string) => (
    <div>
      <label style={{ fontSize: 11, color: "#9C9286", fontWeight: 600, display: "block", marginBottom: 3 }}>{label}</label>
      <input value={val} onChange={(e) => set(e.target.value)} placeholder={ph}
        style={{ width: "100%", padding: "7px 9px", borderRadius: 6, border: "1px solid #E5DDD0", fontSize: 13, outline: "none" }} />
    </div>
  );

  return (
    <div className="fade-in" style={{ background: "#FAF7F2", border: "1px solid #EFE8DA", borderRadius: 9, padding: 13, display: "flex", flexDirection: "column", gap: 9 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <span style={{ fontSize: 13, fontWeight: 700 }}>Nova execução</span>
        <button onClick={onCancel} style={{ background: "none", border: "none", padding: 2 }}><X size={14} color="#9C9286" /></button>
      </div>
      <div style={{ display: "flex", gap: 6 }}>
        {PUBLICOS.map((p) => (
          <button key={p.key} onClick={() => setPub(p.key)}
            style={{ flex: 1, padding: "7px 5px", borderRadius: 7, fontSize: 12, fontWeight: 600, border: pub === p.key ? `1.5px solid ${p.color}` : "1px solid #E5DDD0", background: pub === p.key ? p.color : "#fff", color: pub === p.key ? "#fff" : "#6B6259", display: "flex", flexDirection: "column", alignItems: "center", gap: 2 }}>
            <p.icon size={13} />{p.label}
          </button>
        ))}
      </div>
      {fi("Solução / evento", sol, setSol, "Ex: Palestra Educação Empreendedora")}
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
        <div>
          <label style={{ fontSize: 11, color: "#9C9286", fontWeight: 600, display: "block", marginBottom: 3 }}>Mês de execução</label>
          <select value={mes} onChange={(e) => setMes(e.target.value)} style={{ width: "100%", padding: "7px 9px", borderRadius: 6, border: "1px solid #E5DDD0", fontSize: 13, background: "#fff" }}>
            <option value="">Selecionar…</option>
            {MESES.map((m) => <option key={m} value={m}>{m}</option>)}
          </select>
        </div>
        {fi("Cód. evento (FOCO)", ce, setCe, "EV-12345")}
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
        {fi("Código da solução", cs, setCs, "212000113280")}
        {fi("Código FOCO", cf, setCf, "S26NA1PA580")}
      </div>
      <div style={{ display: "flex", gap: 7, marginTop: 2 }}>
        <button onClick={() => { if (sol.trim()) onSubmit({ publico: pub, solucao: sol.trim(), mes, codSolucao: cs.trim(), codFoco: cf.trim(), codEvento: ce.trim() }); }}
          style={{ flex: 1, padding: "9px", borderRadius: 8, background: "#1F4D3D", color: "#fff", border: "none", fontWeight: 600, fontSize: 13.5 }}>
          Salvar execução
        </button>
        <button onClick={onCancel} style={{ padding: "9px 14px", borderRadius: 8, background: "#fff", color: "#6B6259", border: "1px solid #E5DDD0", fontWeight: 600, fontSize: 13.5 }}>
          Cancelar
        </button>
      </div>
    </div>
  );
}
